(function(root){
'use strict';
const X=typeof module==='object'&&module.exports?require('./experience-core.js'):root.THExperience;
function quickStart(data,C){const E=C.escape,a=X.recommendations(data)[0]||[...data.articles].sort((a,b)=>a.minutes-b.minutes)[0];return `<div class="hero-quickstart"><div class="quickstart-heading"><span class="quickstart-clock" aria-hidden="true">5′</span><div><strong>Bạn có 5 phút?</strong><span>Mở một điều dễ hiểu ngay hôm nay.</span></div><label class="sr-only" for="hero-interest">Chủ đề đọc nhanh</label><select id="hero-interest"><option value="all">Chọn chủ đề</option>${data.categories.map(c=>`<option value="${c.id}">${E(c.short||c.name)}</option>`).join('')}</select></div><a class="quickstart-link" id="hero-start" data-experience-article="${a.id}" href="bai-viet/${a.id}.html"><span><small id="hero-start-meta">${a.minutes} phút đọc · Bắt đầu từ nền tảng</small><strong id="hero-start-title">${E(a.title)}</strong></span><b aria-hidden="true">↗</b></a></div>`;}
function hero(data,C){const E=C.escape,featured=data.articles.find(a=>a.featured)||data.articles[0],ai=data.articles.find(a=>a.category==='ai')||featured,art=C.image(data.config.heroImage,400000)||'assets/horizon-portal.webp',first=data.categories[0],second=data.categories[1]||first;return `<section class="horizon-hero" id="trang-chu"><div class="horizon-hero-grid" aria-hidden="true"></div><div class="container horizon-hero-layout"><div class="horizon-copy"><div class="eyebrow horizon-kicker"><span class="live-dot"></span>TECH HORIZON / MỘT GÓC NHÌN MỚI</div><h1>Hiểu công nghệ.<br><span>Mở rộng<br>góc nhìn.</span><i aria-hidden="true">↗</i></h1><p data-exp-description>${E(data.config.description)}</p>${quickStart(data,C)}<div class="horizon-actions"><a class="button button-blue" href="#diem-bat-dau">Khám phá theo nhu cầu <span aria-hidden="true">↗</span></a><a class="horizon-secondary" href="thuc-hanh.html"><span class="horizon-play" aria-hidden="true">✳</span>Chọn một việc để thử</a></div><div class="horizon-signature"><span class="horizon-line"></span><span data-exp-tagline>${E(data.config.tagline)}</span></div></div><div class="horizon-visual" id="horizon-visual"><div class="horizon-scene"><img class="horizon-scene-img" id="horizon-scene-image" src="${E(art)}" width="1920" height="1072" alt="${C.image(data.config.heroImage,400000)?'Ảnh bìa của kênh':'Vòng kim loại và kính mở ra một đường chân trời ánh sáng xanh'}" fetchpriority="high"><div class="horizon-scene-shade" aria-hidden="true"></div></div><div class="horizon-coordinate" aria-hidden="true"><span>01 / EXPLORE</span><span>GÓC NHÌN MỞ HƠN.</span></div><a class="horizon-orbit-chip chip-ai" href="chuyen-muc/${first.id}.html"><span aria-hidden="true">✳</span>${E(first.name)} <b aria-hidden="true">↗</b></a><a class="horizon-orbit-chip chip-device" href="chuyen-muc/${second.id}.html"><span aria-hidden="true">⌘</span>${E(second.name)} <b aria-hidden="true">↗</b></a><div class="horizon-art-label" aria-hidden="true">THE NEXT<br><strong>PERSPECTIVE.</strong></div><a class="horizon-lab-note" data-experience-article="${ai.id}" href="bai-viet/${ai.id}.html"><img src="assets/ai-lab-preview.png" width="140" height="79" alt="" loading="lazy"><span><small>TỪ GÓC LAB</small><strong>${E(ai.title)}</strong><b>Khám phá cẩm nang ↗</b></span></a><button class="horizon-motion" id="experience-motion" aria-pressed="false">Giảm chuyển động <span aria-hidden="true">Ⅱ</span></button></div></div><div class="container horizon-bottom"><a href="#diem-bat-dau"><span aria-hidden="true">↓</span>Cuộn để mở một góc nhìn</a><span>KHÁM PHÁ · HIỂU RÕ · ỨNG DỤNG</span><a data-experience-article="${featured.id}" href="bai-viet/${featured.id}.html">Bắt đầu với bài nổi bật <span aria-hidden="true">↗</span></a></div></section>`;}
function strip(data){return `<div class="horizon-strip"><div class="container"><span><i aria-hidden="true">✳</i>MỖI ĐIỀU BẠN TÒ MÒ, MỘT ĐIỂM BẮT ĐẦU.</span><span>${data.articles.length} CẨM NANG</span><span>${data.glossary?.length||0} THUẬT NGỮ</span><a href="studio.html">6 CÔNG CỤ THỰC HÀNH ↗</a></div></div>`;}
function recommendation(a,data,C,{lead=false,index=0}={}){const E=C.escape,cat=data.categories.find(c=>c.id===a.category),image=C.image(a.customImage,250000)||'assets/'+a.image+'.svg';return `<article class="discovery-card${lead?' discovery-lead':''}"><div class="discovery-card-top"><span class="discovery-tag">${E(cat?.short||cat?.name||'Cẩm nang')}</span><span>${a.minutes} phút đọc</span></div>${lead?`<div class="discovery-art" aria-hidden="true"><img src="${E(image)}" width="260" height="160" alt="" loading="lazy"></div>`:''}<span class="discovery-order">${lead?'BẮT ĐẦU TỪ ĐÂY':'GÓC NHÌN KHÁC / '+String(index+1).padStart(2,'0')}</span><h3><a data-experience-article="${a.id}" href="bai-viet/${a.id}.html">${E(a.title)}</a></h3><p><span class="discovery-benefit">Điều bạn mang theo</span>${E(a.takeaway)}</p><a class="discovery-read" data-experience-article="${a.id}" href="bai-viet/${a.id}.html">${lead?'Đọc bài này trước':'Khám phá cẩm nang'} <span aria-hidden="true">↗</span></a></article>`;}
function recommendationList(items,data,C){return items.map((a,i)=>recommendation(a,data,C,{lead:i===0,index:i})).join('');}
function emptyDiscovery(data,C,category){const time=X.availableTime(data,category);return `<div class="discovery-empty"><strong>Chưa có bài vừa khoảng thời gian này.</strong><p>${time?'Bạn có thể tăng thời gian để đọc một cẩm nang trong chủ đề đã chọn.':'Thử một chủ đề khác để mở thêm góc nhìn.'}</p>${time?`<button class="button button-outline" data-discovery-expand="${time}">Đổi sang ${time===120?'thời gian thoải mái':time+' phút'} ↗</button>`:''}<a href="tat-ca.html">Xem toàn bộ cẩm nang ↗</a></div>`;}
function discovery(data,C,X){const E=C.escape,items=X.recommendations(data);return `<section class="container discovery-section" id="diem-bat-dau"><div class="discovery-heading"><div><span class="eyebrow">01 / MỘT LỰA CHỌN VỪA VẶN</span><h2>Bắt đầu từ điều<br><span>bạn muốn làm rõ.</span></h2></div><p>Một bài nên đọc trước, vài góc nhìn để đi tiếp. Chọn theo việc bạn cần và thời gian bạn có.</p></div><div class="discovery-controls"><div class="discovery-topics" role="group" aria-label="Chủ đề bạn quan tâm"><button class="active" data-interest="all" aria-pressed="true">Mọi góc nhìn</button>${data.categories.map(c=>`<button data-interest="${c.id}" aria-pressed="false">${E(c.short||c.name)}</button>`).join('')}</div><div class="discovery-selects"><label>Tôi muốn<select id="discovery-goal"><option value="understand">Hiểu từ đầu</option><option value="practice">Thử làm ngay</option><option value="avoid">Tránh nhầm lẫn</option></select></label><label>Tôi có<select id="discovery-time"><option value="3">3 phút</option><option value="5" selected>5 phút</option><option value="10">10 phút</option><option value="120">Thời gian thoải mái</option></select></label></div></div><div class="discovery-results" id="discovery-results" aria-live="polite" aria-label="Cẩm nang được gợi ý">${recommendationList(items,data,C)}</div><div class="discovery-foot"><p id="discovery-status" role="status">${items.length} gợi ý theo chủ đề và thời gian bạn chọn.</p><div><button class="text-button" id="discovery-share">Sao chép lựa chọn ↗</button><button class="text-button" id="discovery-surprise">Một bài bất ngờ ↗</button></div></div><div id="discovery-share-fallback" class="discovery-share-fallback" hidden><label for="discovery-share-url">Liên kết lựa chọn để bạn sao chép</label><input id="discovery-share-url" readonly type="url"></div><noscript><p>Chọn <a href="tat-ca.html">tất cả cẩm nang</a> để khám phá khi JavaScript đang tắt.</p></noscript></section>`;}
function practiceTeaser(data,C){const E=C.escape;return `<section class="container practice-teaser" id="doc-va-lam"><div><span class="eyebrow">THỰC HÀNH / CÓ MỘT VIỆC ĐỂ THỬ</span><h2>Đọc một điều.<br><span>Làm được một việc.</span></h2><p>Chọn một nhiệm vụ nhỏ, đọc phần cần hiểu rồi mở đúng công cụ. Mang kết quả theo bằng phiếu thực hành.</p><a class="button button-blue" href="thuc-hanh.html">Vào Trạm thực hành ↗</a></div><div class="practice-teaser-list">${X.missions(data).map((m,i)=>`<a href="thuc-hanh.html#${m.id}"><span class="mission-symbol" aria-hidden="true">${m.symbol}</span><span><small>0${i+1} / ${E(m.kicker)}</small><strong>${E(m.short)}</strong></span><b aria-hidden="true">↗</b></a>`).join('')}</div></section>`;}
function practice(data,C){const E=C.escape,list=X.missions(data);return `<nav class="mission-nav" aria-label="Chọn nhiệm vụ thực hành">${list.map((m,i)=>`<a href="#${m.id}" data-mission-link="${m.id}" aria-controls="${m.id}"><span>0${i+1}</span>${E(m.short)}<b aria-hidden="true">↗</b></a>`).join('')}</nav><p class="mission-session-note">Dấu chọn và ghi chép chỉ giữ trong lần mở trang này. Cẩm nang và công cụ mở ở tab mới để bạn giữ phiếu. Tải TXT để lưu kết quả lâu dài.</p><div id="mission-panels">${list.map(m=>`<section id="${m.id}" class="mission-panel" aria-labelledby="heading-${m.id}"><div class="mission-panel-head"><div><span class="eyebrow">${E(m.kicker)}</span><h2 id="heading-${m.id}" tabindex="-1">${E(m.title)}</h2><p>${E(m.description)}</p></div><span class="mission-glyph" aria-hidden="true">${m.symbol}</span></div><div class="mission-workflow"><div class="mission-step"><span class="mission-step-no">01</span><div><h3>Đọc để hiểu</h3><p>${m.articles.length?m.articles.length+' cẩm nang · '+m.readMinutes+' phút đọc, chưa gồm thời gian thực hành.':'Chưa có cẩm nang phù hợp trong nội dung hiện tại.'}</p><div class="mission-reading">${m.articles.map(a=>`<a data-experience-article="${a.id}" href="bai-viet/${a.id}.html" target="_blank" rel="noopener"><span>${E(a.title)}<small>${a.minutes} phút đọc <span data-mission-read-state="${a.id}"></span></small></span><b aria-hidden="true">↗</b></a>`).join('')}</div></div></div><div class="mission-step"><span class="mission-step-no">02</span><div><h3>Thử một việc cụ thể</h3><p>${E(m.task)}</p><a class="button button-blue" href="studio.html?mission=${m.id}#${m.tool}" target="_blank" rel="noopener">${E(m.toolTitle)} ↗</a><p class="mission-limit">${E(m.limit)}</p></div></div><div class="mission-step"><span class="mission-step-no">03</span><div><h3>Tự đối chiếu, mang kết quả theo</h3><p>${E(m.outcome)}</p><div class="mission-checklist">${m.checks.map((text,i)=>`<label><input type="checkbox" data-mission-check="${i}"><span>${E(text)}</span></label>`).join('')}</div><label class="mission-reflection-label" for="note-${m.id}">${E(m.note)}</label><textarea id="note-${m.id}" data-mission-note maxlength="2000" rows="4" placeholder="Ghi lại điều bạn đã thử hoặc điều còn muốn tìm hiểu…"></textarea><div class="mission-export"><span data-mission-check-status role="status">0 / ${m.checks.length} mục do bạn tự đánh dấu</span><button class="button button-outline" data-download-mission="${m.id}">Tải phiếu thực hành .txt ↗</button></div></div></div></div></section>`).join('')}</div><noscript><p>Cẩm nang và đường dẫn công cụ vẫn mở được. Bật JavaScript để tải phiếu và dùng Studio.</p></noscript>`;}
function articleNext(a,data,C,p=''){const E=C.escape,m=X.missionForArticle(data,a),next=X.nextArticle(data,a);if(!m&&!next)return '';return `<section class="reader-next-step${next?'':' reader-practice-only'}" data-next-step="${a.id}"><div><span class="eyebrow">TỪ ĐIỀU VỪA HIỂU</span><h2>Cho sự tò mò<br>một bước tiếp theo.</h2>${m?`<p>${E(m.outcome)}</p><a class="button button-blue" href="${p}thuc-hanh.html#${m.id}">${E(m.short)} ↗</a>`:''}</div>${next?`<div class="reader-next-guide"><small>ĐỌC TIẾP TRONG MẠCH CHỦ ĐỀ · ${next.minutes} PHÚT</small><h3><a data-experience-article="${next.id}" href="${p}bai-viet/${next.id}.html">${E(next.title)}</a></h3><p>${E(next.takeaway)}</p><a class="text-button" data-experience-article="${next.id}" href="${p}bai-viet/${next.id}.html">Mở cẩm nang tiếp theo ↗</a></div>`:''}</section>`;}
function studioContext(data,C,id){const m=X.missions(data).find(m=>m.id===id);if(!m)return '';const E=C.escape;return `<aside class="studio-mission-context"><div><span class="eyebrow">BẠN ĐANG THỰC HÀNH</span><strong>${E(m.title)}</strong><p>${E(m.task)}</p></div><a class="text-button" href="thuc-hanh.html#${m.id}">Về phiếu thực hành ↗</a></aside>`;}
function lab(data,C,X){const questions=X.labs(data);if(!questions.length)return '';const q=questions[0],E=C.escape;return `<section class="micro-lab-band" id="giai-ma-nhanh"><div class="container micro-lab-layout"><div class="micro-lab-intro"><span class="eyebrow">TH LAB / MỖI CÂU HỎI, MỘT ĐIỀU SÁNG TỎ</span><h2>Khoan đã.<br><span>Bạn có chắc?</span></h2><p>Một vài hiểu nhầm nhỏ vẫn thường gặp.<br>Chọn cách bạn nghĩ, rồi cùng mở lời giải.</p><div class="micro-orbit" aria-hidden="true"><span>?</span><i></i><b>TH</b></div></div><div class="micro-lab-card"><div class="micro-lab-top"><span id="micro-topic">${q.topic}</span><span id="micro-position">01 / ${String(questions.length).padStart(2,'0')}</span></div><h3 id="micro-question" tabindex="-1">${E(q.question)}</h3><div id="micro-answers" class="micro-answers">${q.answers.map((text,i)=>`<button data-micro-answer="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span>${E(text)}<i aria-hidden="true">↗</i></button>`).join('')}</div><div class="micro-feedback" id="micro-feedback" role="status" hidden></div><div class="micro-lab-bottom"><div><label for="micro-progress" id="micro-progress-label">0 / ${questions.length} góc nhìn đã mở</label><progress id="micro-progress" value="0" max="${questions.length}"></progress></div><button class="text-button" id="micro-next">Câu tiếp theo →</button></div><noscript><p>Mở <a href="bai-viet/${q.article}.html">cẩm nang giải thích</a> để đọc đầy đủ.</p></noscript></div></div></section>`;}
const api={hero,strip,discovery,lab,recommendation,recommendationList,emptyDiscovery,practiceTeaser,practice,articleNext,studioContext};if(typeof module==='object'&&module.exports)module.exports=api;else root.THExperienceMarkup=api;
})(typeof window!=='undefined'?window:globalThis);
